import fs from 'fs';

const path='src/App.jsx';
let app=fs.readFileSync(path,'utf8');
const start=app.indexOf('const TIPS_DATA = [');
if(start<0) throw new Error('TIPS_DATA not found');
const end=app.indexOf('\n];',start);
if(end<0) throw new Error('TIPS_DATA closing bracket not found');
const block=app.slice(start,end);
const ids=[...block.matchAll(/id:\s*"t(\d+)"/g)].map(m=>Number(m[1]));
const titles=new Set([...block.matchAll(/title:\s*\{\s*ko:\s*"([^"]+)"/g)].map(m=>m[1]));
if(!ids.length) throw new Error('PetInfo IDs not found');
const maxId=Math.max(...ids);
if(maxId<338) throw new Error(`Expected dataset through at least t338, found t${maxId}`);

const candidates=[
{category:'dog',featured:true,titleKo:'산책 전에는 목줄과 하네스의 잠금 상태를 한 번 더 확인해요',titleEn:'Check leash and harness fasteners before walks',summaryKo:'출발 직전 연결부와 버클을 확인하면 산책 중 이탈 위험을 줄이는 데 도움이 돼요.',summaryEn:'A quick pre-walk check of clips and buckles can help reduce escape risk.',bodyKo:'현관을 나서기 전에 리드줄 고리, 하네스 버클, 인식표가 제대로 고정되어 있는지 확인하세요. 마모되거나 갈라진 부품은 미리 교체하고 체형에 맞게 너무 헐겁거나 조이지 않도록 조절하세요.',bodyEn:'Before leaving home, check the leash clip, harness buckles, and ID tag. Replace worn parts and adjust the fit so it is secure without being overly tight.'},
{category:'dog',featured:false,titleKo:'더운 날 산책은 그늘과 휴식 지점을 미리 정해두면 좋아요',titleEn:'Plan shade and rest stops on hot-weather walks',summaryKo:'짧은 산책이라도 쉬어갈 그늘과 물을 준비하면 과열 위험을 줄이는 데 도움이 돼요.',summaryEn:'Even short walks are safer when shade, rest, and water are planned in hot weather.',bodyKo:'기온이 높은 날에는 한낮을 피하고 그늘이 있는 경로를 선택하세요. 헐떡임이 심해지거나 걷기를 거부하면 즉시 쉬고 시원한 곳으로 이동하세요. 열사병이 의심되면 신속히 동물병원에 연락하세요.',bodyEn:'Avoid the hottest part of the day and choose shaded routes. Stop promptly if panting becomes intense or your dog refuses to continue. Suspected heatstroke requires urgent veterinary care.'},
{category:'cat',featured:true,titleKo:'고양이 화장실 모래는 한 번에 전부 바꾸기보다 상태를 보며 관리해요',titleEn:'Manage litter changes gradually when possible',summaryKo:'갑작스러운 환경 변화에 민감한 고양이는 모래 상태와 선호를 함께 살펴요.',summaryEn:'Cats sensitive to change may benefit from gradual litter management and attention to preference.',bodyKo:'오염된 부분은 매일 치우고 전체 교체 주기는 제품 안내와 고양이 반응에 맞추세요. 모래 종류를 바꿀 때는 기존 모래와 새 모래를 일정 기간 섞어 적응을 돕는 방법도 고려할 수 있어요.',bodyEn:'Scoop soiled litter daily and follow product guidance for full changes. When switching litter types, gradually mixing old and new litter can help some cats adapt.'},
{category:'cat',featured:false,titleKo:'고양이 식사 공간과 잠자는 공간은 서로 방해되지 않게 배치해요',titleEn:'Separate cat feeding and sleeping areas when possible',summaryKo:'먹고 쉬는 공간을 구분하면 일상 동선을 더 편안하게 만들 수 있어요.',summaryEn:'Separating feeding and resting spaces can make daily routines more comfortable for cats.',bodyKo:'밥그릇을 잠자리 바로 옆이나 소음이 많은 가전제품 근처에 두기보다 조용하고 접근하기 쉬운 위치를 선택하세요. 여러 마리라면 서로 경쟁하지 않도록 급여 위치를 나누는 것도 도움이 됩니다.',bodyEn:'Choose a quiet, accessible feeding location rather than placing bowls directly beside beds or noisy appliances. In multi-cat homes, separate feeding areas may reduce competition.'},
{category:'health',featured:true,titleKo:'기침이나 재채기가 반복되면 발생 시간과 상황을 기록해요',titleEn:'Record timing and triggers of repeated coughing or sneezing',summaryKo:'언제, 얼마나 자주 나타나는지 기록하면 진료 시 상태를 설명하는 데 도움이 돼요.',summaryEn:'Tracking when and how often coughing or sneezing occurs can help during veterinary evaluation.',bodyKo:'운동 후인지, 잠에서 깬 뒤인지, 특정 환경에서 반복되는지 기록하고 가능하면 짧은 영상을 남기세요. 호흡이 힘들어 보이거나 잇몸색이 이상하면 지체하지 말고 즉시 진료를 받아야 합니다.',bodyEn:'Note whether episodes occur after activity, waking, or in a particular environment, and record a short video if possible. Labored breathing or abnormal gum color requires urgent veterinary attention.'},
{category:'health',featured:false,titleKo:'배변 횟수와 변 상태가 갑자기 달라지면 며칠간 기록해요',titleEn:'Track sudden changes in stool frequency or appearance',summaryKo:'배변 패턴 변화는 식이와 건강 상태를 확인하는 데 중요한 단서가 될 수 있어요.',summaryEn:'Changes in stool patterns can provide useful clues about diet and health.',bodyKo:'횟수, 색, 형태, 점액이나 피가 섞였는지 등을 관찰하세요. 반복되는 설사, 혈변, 심한 변비, 구토나 식욕저하가 함께 있으면 동물병원에 상담하세요.',bodyEn:'Observe frequency, color, form, and any mucus or blood. Recurrent diarrhea, blood in stool, severe constipation, or changes accompanied by vomiting or appetite loss should be discussed with a veterinarian.'},
{category:'life',featured:true,titleKo:'반려동물용 담요와 방석은 세탁 주기를 정해 관리해요',titleEn:'Set a regular cleaning schedule for pet bedding',summaryKo:'자주 사용하는 침구를 정기적으로 세탁하면 냄새와 오염 관리에 도움이 돼요.',summaryEn:'Regularly washing frequently used bedding can help control odor and buildup.',bodyKo:'제품 세탁 안내를 확인하고 충분히 헹군 뒤 완전히 말려 사용하세요. 피부가 민감하다면 향이 강한 세제나 섬유유연제 사용을 줄이고 세탁 후 자극 반응이 없는지 살펴보세요.',bodyEn:'Follow care instructions, rinse thoroughly, and dry bedding completely before reuse. For sensitive pets, minimize strongly scented detergents or fabric softeners and watch for irritation.'},
{category:'life',featured:false,titleKo:'반려동물 사진과 예방접종 기록은 한곳에 정리해두면 좋아요',titleEn:'Keep pet photos and vaccination records organized together',summaryKo:'분실이나 응급 상황에 대비해 기본 기록을 쉽게 찾을 수 있게 정리해요.',summaryEn:'Organized pet identification and vaccination records are easier to access in emergencies.',bodyKo:'최근 전신 사진, 얼굴 사진, 예방접종 내역, 등록번호, 주치의 연락처를 휴대폰이나 클라우드 폴더에 함께 보관하세요. 정보가 바뀌면 주기적으로 업데이트해 두는 것이 좋습니다.',bodyEn:'Keep recent full-body and face photos, vaccination records, registration details, and veterinary contact information together on your phone or cloud storage, and update them when details change.'},
{category:'food',featured:true,titleKo:'습식사료는 개봉 후 보관 시간과 온도를 꼭 확인해요',titleEn:'Check storage time and temperature for opened wet food',summaryKo:'남은 습식사료는 제품 안내에 따라 냉장 보관하고 오래 방치하지 않아요.',summaryEn:'Store leftover wet food according to label directions and avoid leaving it out too long.',bodyKo:'급여 후 남은 습식사료를 실온에 오래 두지 말고 제품 안내에 따라 냉장 보관하세요. 다시 급여할 때 냄새나 상태가 평소와 다르면 버리는 것이 안전합니다.',bodyEn:'Do not leave leftover wet food at room temperature for long. Refrigerate according to package directions and discard food that smells or looks unusual before serving again.'},
{category:'food',featured:false,titleKo:'새 간식은 한 번에 많이 주지 말고 소량부터 시작해요',titleEn:'Introduce new treats in small amounts',summaryKo:'처음 먹는 간식은 적은 양으로 시작해 소화 상태와 반응을 살펴요.',summaryEn:'Start unfamiliar treats in small portions so you can observe digestion and tolerance.',bodyKo:'처음 주는 간식은 소량으로 시작하고 이후 구토, 설사, 가려움 같은 변화가 없는지 확인하세요. 알레르기나 처방식이 있는 반려동물은 새 간식을 주기 전에 수의사와 상의하는 것이 좋습니다.',bodyEn:'Offer only a small amount of a new treat at first and watch for vomiting, diarrhea, itching, or other changes. Pets with allergies or prescription diets should be discussed with a veterinarian before introducing new treats.'},
{category:'training',featured:true,titleKo:'훈련 보상은 성공 직후에 주어야 행동과 연결하기 쉬워요',titleEn:'Give rewards immediately after successful behavior',summaryKo:'행동 직후의 빠른 보상은 무엇을 잘했는지 이해하는 데 도움이 돼요.',summaryEn:'Prompt rewards help pets connect the reward with the behavior that earned it.',bodyKo:'원하는 행동이 나온 직후 1~2초 안에 칭찬이나 작은 보상을 주세요. 시간이 많이 지나 다른 행동을 한 뒤 보상하면 무엇을 강화하는지 혼란스러울 수 있어요.',bodyEn:'Reward the desired behavior within a second or two with praise or a small treat. Delayed rewards may accidentally reinforce a different behavior.'},
{category:'training',featured:false,titleKo:'산책 중 방향 전환 신호는 조용한 곳에서 먼저 연습해요',titleEn:'Practice direction-change cues in quiet places first',summaryKo:'자극이 적은 환경에서 익힌 뒤 실제 산책길로 확장하면 성공률을 높일 수 있어요.',summaryEn:'Learning direction-change cues in a low-distraction area can improve success on real walks.',bodyKo:'집 앞이나 조용한 공간에서 보호자가 방향을 바꿀 때 따라오면 바로 보상하세요. 익숙해진 뒤 사람이나 다른 개가 있는 환경으로 천천히 난이도를 높여 주세요.',bodyEn:'Practice in a quiet area and reward your dog for following when you change direction. Gradually add distractions only after the response becomes reliable.'},
{category:'safety',featured:true,titleKo:'자동차 안에서는 이동장이나 반려동물용 안전장치를 사용해요',titleEn:'Use a carrier or pet restraint in the car',summaryKo:'주행 중 자유롭게 움직이지 않도록 고정하면 급정거 때 부상 위험을 줄이는 데 도움이 돼요.',summaryEn:'Proper restraint can reduce injury risk during sudden stops or collisions.',bodyKo:'반려동물은 뒷좌석의 고정된 이동장이나 자동차용으로 설계된 안전장치를 사용하세요. 운전자 무릎 위나 창밖으로 몸을 내미는 상태로 이동하는 것은 피해야 합니다.',bodyEn:'Use a secured carrier or a restraint designed for vehicle travel, ideally in the rear seat. Avoid allowing pets on the driver’s lap or leaning far out of open windows.'},
{category:'safety',featured:false,titleKo:'현관문 근처에는 리드줄과 인식표를 바로 확인할 수 있게 둬요',titleEn:'Keep leash and ID essentials organized near the door',summaryKo:'외출 전 필요한 장비를 한곳에 두면 누락을 줄이는 데 도움이 돼요.',summaryEn:'Keeping walk essentials together can reduce forgotten safety items before leaving home.',bodyKo:'리드줄, 하네스, 배변봉투, 인식표를 현관 근처 정해진 위치에 두고 출발 전 체크하세요. 문이 열리는 동안 반려동물이 갑자기 뛰어나가지 않도록 기다리기 습관도 함께 유지하세요.',bodyEn:'Store leashes, harnesses, waste bags, and ID tags in one designated place and check them before leaving. Continue practicing calm waiting while the door is open.'},
{category:'grooming',featured:true,titleKo:'발톱은 한 번에 많이 자르기보다 짧게 자주 확인해요',titleEn:'Trim nails conservatively and check them often',summaryKo:'조금씩 자주 관리하면 혈관을 건드릴 위험을 줄이고 적응을 돕기 쉬워요.',summaryEn:'Frequent conservative trimming can reduce the risk of cutting the quick and help pets adapt.',bodyKo:'발톱 끝을 조금씩 다듬고 혈관 위치가 잘 보이지 않으면 무리하지 마세요. 발톱 관리에 강한 스트레스를 보이거나 구조상 자르기 어렵다면 미용사나 동물병원에 도움을 요청하세요.',bodyEn:'Trim only small amounts at a time and stop if the quick is difficult to identify. If nail care causes significant stress or the nails are difficult to trim safely, ask a groomer or veterinary professional for help.'},
{category:'grooming',featured:false,titleKo:'빗질 도구는 털 길이와 피부 상태에 맞춰 선택해요',titleEn:'Choose grooming tools for coat length and skin condition',summaryKo:'도구가 너무 강하거나 맞지 않으면 피부 자극이나 불편함이 생길 수 있어요.',summaryEn:'An overly harsh or unsuitable grooming tool can irritate skin and cause discomfort.',bodyKo:'짧은 털, 긴 털, 이중모 등 털 형태에 맞는 브러시를 사용하고 피부를 세게 긁지 않도록 압력을 조절하세요. 빗질 뒤 붉음이나 통증 반응이 반복되면 도구 사용을 중단하고 상태를 확인하세요.',bodyEn:'Use a brush suited to coat type and avoid scraping the skin. Stop using the tool and check the skin if redness or pain repeatedly appears after grooming.'}
];

const seenCandidates=new Set();
for(const c of candidates){
  if(seenCandidates.has(c.titleKo)) throw new Error(`Duplicate candidate title: ${c.titleKo}`);
  seenCandidates.add(c.titleKo);
  if(titles.has(c.titleKo)) throw new Error(`Existing PetInfo title duplicate: ${c.titleKo}`);
}
if(candidates.length!==16) throw new Error(`Expected 16 candidates, got ${candidates.length}`);
let nextId=maxId+1;
const lines='\n'+candidates.map(c=>`  { id: "t${nextId++}", category: "${c.category}", featured: ${c.featured},\n    title: { ko: ${JSON.stringify(c.titleKo)}, en: ${JSON.stringify(c.titleEn)} },\n    summary: { ko: ${JSON.stringify(c.summaryKo)}, en: ${JSON.stringify(c.summaryEn)} },\n    body: { ko: ${JSON.stringify(c.bodyKo)}, en: ${JSON.stringify(c.bodyEn)} }, sourceDate: "2026-08-28" },`).join('\n');
app=app.slice(0,end)+lines+app.slice(end);
fs.writeFileSync(path,app);
console.log(`Added 16 PetInfo items through t${nextId-1}`);
